// Gelen kutusunu kartlar halinde gösteren HTML sayfası (script yok, sayfa kendini yeniler).
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const zaman = (v) => { const d = new Date(v); return isNaN(d) ? String(v || '') : d.toLocaleString('tr-TR', { timeZone: 'Europe/Istanbul', dateStyle: 'short', timeStyle: 'short' }); };
const satirlar = $input.all().map((i) => i.json).filter((r) => r.Mesaj_ID);
satirlar.sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)));

const renk = { 'Eksik evrak': '#d97706', 'Yeni başvuru': '#2563eb', 'Durum sorgusu': '#6b7280', 'Şikâyet': '#dc2626', 'İnceleme gerekli': '#7c3aed' };
const durumRenk = { 'Yeni': '#9ca3af', 'Yanıt hazır': '#16a34a', 'Belge bekleniyor': '#d97706' };

const kartlar = satirlar.map((r) => {
  const isleniyor = r.Durum === 'Yeni';
  const durum = isleniyor ? 'İşleniyor...' : esc(r.Durum);
  const sonuc = isleniyor
    ? '<p class="bekle">Yapay zekâ henüz okumadı. Ana süreç her dakika çalışır.</p>'
    : '<p><b>Özet:</b> ' + esc(r.Ozet) + '</p>'
      + (r.Eksik_belge ? '<p><b>Eksik belge:</b> ' + esc(r.Eksik_belge) + '</p>' : '')
      + '<p class="alt">Yanıt taslağı (gönderilmedi)</p><div class="taslak">' + esc(r.Yanit_taslagi) + '</div>';
  return '<section class="kart">'
    + '<div class="ust"><span class="rozet" style="background:' + (durumRenk[r.Durum] || '#6b7280') + '">' + durum + '</span>'
    + (r.Kategori ? '<span class="rozet" style="background:' + (renk[r.Kategori] || '#6b7280') + '">' + esc(r.Kategori) + '</span>' : '')
    + '<span class="tarih">' + esc(zaman(r.Alinma_tarihi)) + '</span></div>'
    + '<h2>' + esc(r.Konu) + '</h2>'
    + '<p class="kim">' + esc(r.Gonderen) + ' &lt;' + esc(r.Gonderen_eposta) + '&gt;' + (r.Ekler ? ' · Ek: ' + esc(r.Ekler) : ' · Ek yok') + '</p>'
    + '<p class="metin">' + esc(r.Metin) + '</p>'
    + sonuc
    + '</section>';
}).join('');

const css = ':root{--bg:#f6f7f9;--kart:#fff;--yazi:#1f2937;--soluk:#6b7280;--cizgi:#e5e7eb;--taslak:#f0f9ff}'
  + '@media(prefers-color-scheme:dark){:root{--bg:#0f1115;--kart:#1a1d24;--yazi:#e5e7eb;--soluk:#9ca3af;--cizgi:#2b303b;--taslak:#10263a}}'
  + '*{box-sizing:border-box}body{margin:0;padding:16px;background:var(--bg);color:var(--yazi);font:15px/1.5 system-ui,sans-serif}'
  + 'main{max-width:820px;margin:0 auto}h1{font-size:20px;margin:4px 0}.not{color:var(--soluk);font-size:13px;margin:0 0 16px}'
  + '.kart{background:var(--kart);border:1px solid var(--cizgi);border-radius:10px;padding:14px 16px;margin-bottom:12px}'
  + '.kart h2{font-size:16px;margin:8px 0 2px}.ust{display:flex;gap:8px;align-items:center;flex-wrap:wrap}'
  + '.rozet{color:#fff;font-size:12px;font-weight:600;padding:2px 9px;border-radius:99px}.tarih{margin-left:auto;color:var(--soluk);font-size:12px}'
  + '.kim{color:var(--soluk);font-size:13px;margin:0 0 8px}.metin{white-space:pre-wrap;margin:0 0 10px}.bekle{color:var(--soluk);font-style:italic}'
  + '.alt{color:var(--soluk);font-size:12px;margin:10px 0 4px}.taslak{white-space:pre-wrap;background:var(--taslak);border-radius:8px;padding:10px 12px}'
  + '.kart p{margin:4px 0}';

const html = '<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
  + '<meta http-equiv="refresh" content="5"><title>Gelen kutusu</title><style>' + css + '</style></head><body><main>'
  + '<h1>Gelen kutusu (' + satirlar.length + ')</h1><p class="not">Sayfa 5 saniyede bir yenilenir. Hiçbir yanıt gerçekten gönderilmez.</p>'
  + (kartlar || '<p class="bekle">Henüz e-posta yok. Mail Gönderme formundan bir e-posta gönderin.</p>')
  + '</main></body></html>';

return [{ json: { html } }];
